#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int x, y, value;
} Die;

int compare(const void *a, const void *b) {
    Die *da = (Die*)a;
    Die *db = (Die*)b;
    if (da->x != db->x) return da->x - db->x;
    return da->y - db->y;
}

int main() {
    int n;
    scanf("%d", &n);
    Die *dice = malloc(n * sizeof(Die));
    for (int i = 0; i < n; i++) {
        scanf("%d %d %d", &dice[i].x, &dice[i].y, &dice[i].value);
    }
    qsort(dice, n, sizeof(Die), compare);

    long long total = 0;
    int i = 0;
    while (i < n) {
        int j = i;
        int maxVal = dice[i].value;
        while (j < n && dice[j].x == dice[i].x && dice[j].y == dice[i].y) {
            if (dice[j].value > maxVal) maxVal = dice[j].value;
            j++;
        }
        if (maxVal > 0) total += maxVal;
        i = j;
    }

    printf("%lld\n", total);
    free(dice);
    return 0;
}

