typedef struct {
    int top, bottom, left, right, front, back;
} Die;

void rotate_north(Die *d) {
    int temp = d->top;
    d->top = d->back;
    d->back = d->bottom;
    d->bottom = d->front;
    d->front = temp;
}

void rotate_south(Die *d) {
    int temp = d->top;
    d->top = d->front;
    d->front = d->bottom;
    d->bottom = d->back;
    d->back = temp;
}

void rotate_west(Die *d) {
    int temp = d->top;
    d->top = d->right;
    d->right = d->bottom;
    d->bottom = d->left;
    d->left = temp;
}

void rotate_east(Die *d) {
    int temp = d->top;
    d->top = d->left;
    d->left = d->bottom;
    d->bottom = d->right;
    d->right = temp;
}

