    if (!best) return 0;

    for (int i = 0; i < N; i++) {
        ll mx = -((ll)1 << 60);
        for (int j = 0; j < 6; j++) {
            ll x;
            scanf("%lld", &x);
            if (x > mx) mx = x;
        }
        best[i] = mx;
    }

    qsort(best, N, sizeof(ll), cmp_ll_desc);

    ll ans = 0;
    for (int i = 0; i < N; i++) {
        if (best[i] > 0) ans += best[i];
        else break;
    }

    printf("%lld\n", ans);

    free(best);
    return 0;
}

