import java.util.*;

public class Main {
    static int N;
    static int[] pos;
    static int[][] faces; // [top, front, right, bottom, back, left]

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        pos = new int[N];
        faces = new int[N][6];
        for (int i = 0; i < N; i++) {
            pos[i] = sc.nextInt();
            for (int j = 0; j < 6; j++) faces[i][j] = sc.nextInt();
        }

        int[] perm = new int[N];
        for (int i = 0; i < N; i++) perm[i] = i;
        int maxScore = Integer.MIN_VALUE;

        do {
            int score = simulate(perm);
            maxScore = Math.max(maxScore, score);
        } while (nextPermutation(perm));

        System.out.println(maxScore);
    }

    static int simulate(int[] order) {
        Map<Integer, Integer> board = new HashMap<>(); // position -> bottom face
        int total = 0;
        for (int idx : order) {
            int p = pos[idx];
            int[] f = faces[idx].clone(); // top,front,right,bottom,back,left
            while (board.containsKey(p)) p++;
            // roll right (p - pos[idx]) times
            int rolls = p - pos[idx];
            for (int r = 0; r < rolls; r++) {
                int newBottom = f[2], newRight = f[0], newTop = f[5], newLeft = f[3];
                f[3] = newBottom; f[2] = newRight; f[0] = newTop; f[5] = newLeft;
            }
            board.put(p, f[3]);
            total += f[3];
        }
        return total;
    }

    static boolean nextPermutation(int[] arr) {
        int n = arr.length, i = n - 2;
        while (i >= 0 && arr[i] >= arr[i+1]) i--;
        if (i < 0) return false;
        int j = n - 1;
        while (arr[j] <= arr[i]) j--;
        int tmp = arr[i]; arr[i] = arr[j]; arr[j] = tmp;
        for (int l = i+1, r = n-1; l < r; l++, r--) { tmp = arr[l]; arr[l] = arr[r]; arr[r] = tmp; }
        return true;
    }
}

