            while (st.hasMoreTokens()) {
                seq.add(Long.parseLong(st.nextToken()));
            }
            sequences.add(seq);
        }

        // For each die, compute best cumulative sum for each possible number of presses
        // up to the length of its sequence.
        int maxPresses = N; // total presses available
        // dp[j] = max score using j total presses, considering processed dice
        long[] dp = new long[maxPresses + 1];
        Arrays.fill(dp, Long.MIN_VALUE / 2);
        dp[0] = 0;

        for (int d = 0; d < N; d++) {
            List<Long> seq = sequences.get(d);
            int len = seq.size();
            // compute prefix sums
            long[] prefix = new long[len + 1];
            for (int i = 0; i < len; i++) {
                prefix[i+1] = prefix[i] + seq.get(i);
            }
            // best value for k presses (k from 1..len)
            long[] best = new long[len + 1];
            best[0] = 0;
            for (int k = 1; k <= len; k++) {
                long maxVal = Long.MIN_VALUE;
                // we can choose to take exactly k presses, but we could also 
                // stop earlier if cumulative sum is better? No, we want exactly k presses 
                // because we are considering using this die k times.
                // However, we might skip some presses? No, we must take first k.
                // So best[k] = prefix[k].
                best[k] = prefix[k];
            }

            // Now do knapsack (0/1 multiple choice: we can choose to take 0..len presses of this die)
            long[] newdp = dp.clone();
            for (int used = 0; used <= maxPresses; used++) {
                if (dp[used] == Long.MIN_VALUE / 2) continue;
                for (int take = 1; take <= len && used + take <= maxPresses; take++) {
                    long val = dp[used] + best[take];
                    if (val > newdp[used + take]) {
                        newdp[used + take] = val;
                    }
                }
            }
            dp = newdp;
        }

        // Answer is max over dp[0..maxPresses]
        long ans = 0;
        for (int i = 0; i <= maxPresses; i++) {
            if (dp[i] > ans) ans = dp[i];
        }
        System.out.println(ans);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N;
        try {
            N = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        /*
         Assumed input format:
         For each die:
           - 6 integers: values on faces
           - N integers: score obtained on the 1st, 2nd, ..., N-th press of this die
         However the statement provided here is missing the exact format.

         The intended solution for this kind of problem is:
         dp[t] = maximum score after exactly t total presses
         For each die i, choose how many times k (0..N) to press it, gaining pref[i][k],
         and do knapsack over total presses = N.

         Since the statement says each die's behavior is predetermined, the input usually
         provides the resulting bottom values for successive presses, or enough information
         to derive them. We implement the generic DP once those per-die gains are read.

         To remain runnable, we interpret the input as:
           N
           then for i=0..N-1:
             N integers a[i][1..N], where a[i][k] is the score from the k-th press of die i
         Then pref[i][k] = sum of first k values.
        */

        long[][] pref = new long[N][N + 1];
        for (int i = 0; i < N; i++) {
            for (int k = 1; k <= N; k++) {
                pref[i][k] = pref[i][k - 1] + fs.nextLong();
            }
        }

        long[] dp = new long[N + 1];
        Arrays.fill(dp, Long.MIN_VALUE / 4);
        dp[0] = 0;

        for (int i = 0; i < N; i++) {
            long[] ndp = new long[N + 1];
            Arrays.fill(ndp, Long.MIN_VALUE / 4);
            for (int used = 0; used <= N; used++) {
                if (dp[used] <= Long.MIN_VALUE / 8) continue;
                for (int k = 0; used + k <= N; k++) {
                    ndp[used + k] = Math.max(ndp[used + k], dp[used] + pref[i][k]);
                }
            }
            dp = ndp;
        }

        System.out.println(dp[N]);
    }
}
